use std::fs;
use std::path::{Path, PathBuf};

use callisto_model::{
    ApplyPermit, DepKind, DepSpec, DependencyEntry, Ecosystem, ManifestDecl, ManifestError, ManifestFormat,
    ManifestRole, Version, VersionGrammar, VersionReq, WorkspaceKind,
};
use indexmap::IndexMap;
use serde_json::{Map, Value};

use crate::{Manifest, NpmRole, OpenContext};

pub struct PackageJson {
    path: PathBuf,
    absolute: PathBuf,
    role: ManifestRole,
    doc: Map<String, Value>,
    fingerprint: FormatFingerprint,
    npm_workspace_kind: Option<WorkspaceKind>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct FormatFingerprint {
    indent: Indent,
    trailing_newline: bool,
    common: crate::common::FormatFingerprint,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Indent {
    Spaces(u8),
    Tabs,
    DefaultTwoSpaces,
}

impl PackageJson {
    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
        let rel_path = decl.path.clone();
        let abs_path = ctx.workspace_root.join(&rel_path);

        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
            path: rel_path.clone(),
            message: e.to_string(),
        })?;

        let common_fp = crate::common::FormatFingerprint::detect(&content);
        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
        let fingerprint = detect_fingerprint(clean_content, common_fp);

        let doc: Map<String, Value> = serde_json::from_str(clean_content).map_err(|e| ManifestError::Parse {
            path: rel_path.clone(),
            format: ManifestFormat::PackageJson,
            message: e.to_string(),
        })?;

        Ok(PackageJson {
            path: rel_path,
            absolute: abs_path,
            role: decl.role.clone(),
            doc,
            fingerprint,
            npm_workspace_kind: ctx.npm_workspace_kind,
        })
    }
}

fn detect_fingerprint(content: &str, common: crate::common::FormatFingerprint) -> FormatFingerprint {
    let trailing_newline = content.ends_with('\n');

    let mut indent = Indent::DefaultTwoSpaces;
    for line in content.lines() {
        let trimmed_start = line.trim_start();
        if trimmed_start.starts_with('"') && line.len() > trimmed_start.len() {
            let leading = &line[..line.len() - trimmed_start.len()];
            if leading.contains('\t') {
                indent = Indent::Tabs;
            } else {
                indent = Indent::Spaces(leading.len() as u8);
            }
            break;
        }
    }

    FormatFingerprint {
        indent,
        trailing_newline,
        common,
    }
}

fn format_json_pretty(map: &IndexMap<&String, &Value>, indent_str: &str) -> Result<String, ManifestError> {
    use serde::Serialize;
    let buf = Vec::new();
    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
    let mut serializer = serde_json::Serializer::with_formatter(buf, formatter);
    map.serialize(&mut serializer)
        .map_err(|e| ManifestError::FormattingNotPreserved {
            path: std::path::PathBuf::new(),
            message: format!("JSON serialization failed: {e}"),
        })?;
    let bytes = serializer.into_inner();
    let mut out = String::from_utf8(bytes).map_err(|e| ManifestError::FormattingNotPreserved {
        path: std::path::PathBuf::new(),
        message: format!("JSON serialization produced invalid UTF-8: {e}"),
    })?;
    out.push('\n');
    Ok(out)
}

/// Extracts `name` from an already-parsed `package.json` document. Pure and
/// I/O-free -- see [`crate::cargo::cargo_package_name`]'s doc comment for
/// why this exists as a standalone function rather than only living inside
/// [`Manifest::package_name`].
pub fn npm_package_name(doc: &serde_json::Map<String, serde_json::Value>) -> Option<&str> {
    doc.get("name").and_then(|n| n.as_str())
}

/// [`crate::read_identity`]'s `package.json` implementation: parses
/// `source` and extracts `name` plus a [`crate::VersionSource::Literal`]
/// for `version` (npm has no workspace-inherited-version concept, unlike
/// Cargo).
pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
    let doc: Map<String, Value> = serde_json::from_str(clean).map_err(|e| ManifestError::Parse {
        path: path.to_path_buf(),
        format: ManifestFormat::PackageJson,
        message: e.to_string(),
    })?;

    let name = npm_package_name(&doc).map(str::to_string);
    let version = doc
        .get("version")
        .and_then(|v| v.as_str())
        .map(|s| crate::VersionSource::Literal(s.to_string()));

    Ok(crate::ManifestIdentity { name, version })
}

/// Reads `napi.targets` from an already-parsed `package.json` value.
/// `Ok(None)` when `napi` or `napi.targets` is absent -- not every napi
/// package.json declares platform targets. `Err` when `napi.targets` is
/// present but is not a JSON array of strings.
///
/// The single implementation both `NapiTargetsIndex::load` (lenient: `.ok()`
/// this, treating a malformed value the same as absent) and
/// `matrix::read_napi_targets` (strict: propagates the error) build their
/// differing policies on top of -- see each call site for which it chooses.
pub fn read_napi_targets(path: &Path, val: &Value) -> Result<Option<Vec<String>>, ManifestError> {
    let Some(napi) = val.get("napi") else {
        return Ok(None);
    };
    let Some(targets) = napi.get("targets") else {
        return Ok(None);
    };

    let arr = targets.as_array().ok_or_else(|| ManifestError::Parse {
        path: path.to_path_buf(),
        format: ManifestFormat::PackageJson,
        message: "napi.targets must be a JSON array of strings".to_string(),
    })?;

    let mut out = Vec::with_capacity(arr.len());
    for item in arr {
        let s = item.as_str().ok_or_else(|| ManifestError::Parse {
            path: path.to_path_buf(),
            format: ManifestFormat::PackageJson,
            message: "napi.targets entries must all be strings".to_string(),
        })?;
        out.push(s.to_string());
    }
    Ok(Some(out))
}

/// The napi-rs binary name: `napi.binaryName`, else the deprecated `napi.name`, else napi-rs's `index`.
pub fn napi_binary_name(val: &Value) -> String {
    let napi = val.get("napi");
    ["binaryName", "name"]
        .iter()
        .find_map(|key| napi.and_then(|napi| napi.get(key)).and_then(Value::as_str))
        .unwrap_or("index")
        .to_owned()
}

/// Detects whether `doc` (an already-parsed `package.json` document) declares
/// itself a napi-rs platform package -- `os`+`cpu` constraint arrays both
/// present and non-empty -- and if so, its platform/arch/abi. Pure and
/// I/O-free: the single implementation [`PackageJson::npm_role`] builds on,
/// so platform-role detection is available from an already-open `Manifest`
/// handle (e.g. one served from `callisto-graph`'s `manifest_cache`) without
/// a second `fs::read` of the same file.
/// `npm_role_from_doc` over raw `package.json` source, for callers (workspace
/// discovery) that have not opened a manifest handle. `None` on invalid JSON.
pub fn npm_role_from_source(source: &str) -> Option<NpmRole> {
    match serde_json::from_str::<Value>(source).ok()? {
        Value::Object(doc) => npm_role_from_doc(&doc),
        _ => None,
    }
}

/// True when raw `package.json` `source` sets `"private": true`. `false` on
/// invalid JSON or an absent/non-true `private` field.
pub fn npm_declares_private(source: &str) -> bool {
    match serde_json::from_str::<Value>(source).ok() {
        Some(Value::Object(doc)) => doc.get("private").and_then(Value::as_bool).unwrap_or(false),
        _ => false,
    }
}

fn npm_role_from_doc(doc: &Map<String, Value>) -> Option<NpmRole> {
    let has_os = doc.get("os").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
    let has_cpu = doc.get("cpu").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());

    if !has_os || !has_cpu {
        return None;
    }

    let platform = doc
        .get("os")
        .and_then(|v| v.as_array())
        .and_then(|a| a.first())
        .and_then(|v| v.as_str())
        .map(str::to_string)?;

    let arch = doc
        .get("cpu")
        .and_then(|v| v.as_array())
        .and_then(|a| a.first())
        .and_then(|v| v.as_str())
        .map(str::to_string)?;

    // npm's standard `os`/`cpu` manifest fields have no libc/ABI concept at
    // all, so a real disk-discovered Linux napi platform package always
    // produces `abi: None` here -- but `napi.rs::role_to_triple`'s Linux
    // match arms all require a concrete ABI, meaning such a package could
    // never resolve to its triple. napi-rs's own package-generation
    // convention encodes the ABI in the package *name*'s suffix instead
    // (e.g. "@scope/pkg-linux-x64-gnu"), so infer it from there when the
    // platform is linux.
    let abi = if platform == "linux" {
        doc.get("name")
            .and_then(|v| v.as_str())
            .and_then(napi_linux_abi_from_package_name)
    } else {
        None
    };

    Some(NpmRole::Platform { platform, arch, abi })
}

/// Infers a Linux napi-rs platform package's libc ABI from its package
/// name's trailing suffix. Returns `None` when the name has no recognized
/// suffix -- this infers when the signal is present, it doesn't invent an
/// ABI that isn't actually there.
fn napi_linux_abi_from_package_name(name: &str) -> Option<String> {
    for abi in ["gnueabihf", "gnu", "musl"] {
        if name.ends_with(&format!("-{abi}")) {
            return Some(abi.to_string());
        }
    }
    None
}

impl Manifest for PackageJson {
    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
        let indent_str = match self.fingerprint.indent {
            Indent::Spaces(n) => " ".repeat(n as usize),
            Indent::Tabs => "\t".to_string(),
            Indent::DefaultTwoSpaces => "  ".to_string(),
        };

        let mut map = IndexMap::new();
        for (k, v) in &self.doc {
            map.insert(k, v);
        }

        let mut out = format_json_pretty(&map, &indent_str)?;
        if self.fingerprint.common.line_ending == crate::common::LineEnding::CrLf {
            out = out.replace("\r\n", "\n").replace('\n', "\r\n");
        }

        // Trailing-newline trimming must happen strictly between the
        // line-ending conversion (above, so a trimmed "\r\n" is measured
        // correctly) and the BOM prepend (below, so a BOM byte is never
        // mistaken for part of the trailing newline) -- this ordering
        // dependency is why npm's own trailing_newline concern can't route
        // through `common::FormatFingerprint::apply`'s single combined
        // crlf-then-bom step the way cargo/python's simpler persist paths do.
        if !self.fingerprint.trailing_newline && out.ends_with('\n') {
            if out.ends_with("\r\n") {
                out.truncate(out.len() - 2);
            } else {
                out.truncate(out.len() - 1);
            }
        }

        if self.fingerprint.common.has_bom {
            out = format!("\u{FEFF}{}", out);
        }

        crate::atomic::atomic_write(&self.absolute, &out, permit).map_err(|e| ManifestError::Write {
            path: self.path.clone(),
            message: e.to_string(),
        })?;
        crate::record_persist_call();
        Ok(())
    }

    fn path(&self) -> &Path {
        &self.path
    }

    fn ecosystem(&self) -> Ecosystem {
        Ecosystem::Npm
    }

    fn is_publishable(&self) -> bool {
        if self.doc.get("name").is_none() {
            return false;
        }
        if let Some(b) = self.doc.get("private").and_then(|p| p.as_bool()) {
            if b {
                return false;
            }
        }
        true
    }

    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
        if !self.is_publishable() {
            return vec![callisto_model::PublishTarget::None];
        }
        // Read `publishConfig.registry` from package.json, the standard npm
        // mechanism for targeting a private registry. When set, `npm publish`
        // must receive `--registry <url>`; when absent, the public registry is
        // used (npm's built-in default).
        let publish_config = self.doc.get("publishConfig");
        let registry = publish_config
            .and_then(|pc| pc.get("registry"))
            .and_then(|r| r.as_str())
            .map(|s| s.to_string());
        // Read `publishConfig.access` to propagate the operator's explicit
        // access intent. npm's `--access` CLI flag overrides publishConfig.access,
        // so callisto must read it here and honour it in release planning rather than
        // blindly passing `--access public` for all scoped packages. Any value
        // other than the two npm recognises (including absence) is `None`,
        // not an error -- an unrecognised value here isn't this layer's job
        // to validate.
        let access = publish_config
            .and_then(|pc| pc.get("access"))
            .and_then(|a| a.as_str())
            .and_then(|s| match s {
                "public" => Some(callisto_model::NpmAccess::Public),
                "restricted" => Some(callisto_model::NpmAccess::Restricted),
                _ => None,
            });
        vec![callisto_model::PublishTarget::Npm { registry, access }]
    }

    fn role(&self) -> ManifestRole {
        self.role.clone()
    }

    fn package_name(&self) -> Result<String, ManifestError> {
        let name = npm_package_name(&self.doc).ok_or_else(|| ManifestError::MissingField {
            path: self.path.clone(),
            field: "name",
        })?;
        Ok(name.to_string())
    }

    fn current_version(&self) -> Result<Version, ManifestError> {
        let raw = self
            .doc
            .get("version")
            .and_then(|v| v.as_str())
            .ok_or_else(|| ManifestError::MissingField {
                path: self.path.clone(),
                field: "version",
            })?;

        Version::parse(raw, VersionGrammar::SemVer).map_err(|source| ManifestError::InvalidVersion {
            path: self.path.clone(),
            raw: raw.to_string(),
            source,
        })
    }

    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
        self.doc
            .insert("version".to_string(), Value::String(v.render().to_string()));
        Ok(())
    }

    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
        let mut entries = Vec::new();

        for (section_name, kind) in [
            ("dependencies", DepKind::Runtime),
            ("devDependencies", DepKind::Dev),
            ("peerDependencies", DepKind::Peer),
            ("optionalDependencies", DepKind::Optional),
        ] {
            if let Some(obj) = self.doc.get(section_name).and_then(|v| v.as_object()) {
                for (name, val) in obj {
                    if let Some(v_str) = val.as_str() {
                        let spec = parse_npm_spec_str(v_str, self.npm_workspace_kind);
                        entries.push(DependencyEntry {
                            name: name.clone(),
                            package_name: name.clone(),
                            kind,
                            spec,
                            inherited: false,
                        });
                    }
                }
            }
        }

        Box::new(entries.into_iter())
    }

    fn update_dependency_spec(
        &mut self,
        name: &str,
        kind: DepKind,
        new: DepSpec,
        _permit: &ApplyPermit,
    ) -> Result<(), ManifestError> {
        if kind == DepKind::Build {
            return Err(ManifestError::DependencyNotFound {
                path: self.path.clone(),
                name: name.to_string(),
                kind,
            });
        }

        let section_name = match kind {
            DepKind::Runtime => "dependencies",
            DepKind::Dev => "devDependencies",
            DepKind::Peer => "peerDependencies",
            DepKind::Optional => "optionalDependencies",
            DepKind::Build => unreachable!(),
        };

        // Validate that the target dependency actually exists in the primary
        // section *before* mutating anything. This guarantees that a failed
        // update (dependency not found) leaves self.doc byte-for-byte
        // unchanged, including the overrides/resolutions tables below.
        let updated_in_section = self
            .doc
            .get(section_name)
            .and_then(|v| v.as_object())
            .is_some_and(|section| section.contains_key(name));

        if !updated_in_section {
            return Err(ManifestError::DependencyNotFound {
                path: self.path.clone(),
                name: name.to_string(),
                kind,
            });
        }

        if let Some(section) = self.doc.get_mut(section_name).and_then(|v| v.as_object_mut()) {
            section.insert(name.to_string(), Value::String(new.render()));
        }

        for extra in ["overrides", "resolutions"] {
            if let Some(tbl) = self.doc.get_mut(extra).and_then(|v| v.as_object_mut()) {
                if tbl.get(name).is_some_and(|v| v.is_string()) {
                    tbl.insert(name.to_string(), Value::String(new.render()));
                }
            }
        }

        Ok(())
    }

    fn update_optional_dependencies(
        &mut self,
        updates: &[(String, Version)],
        _permit: &ApplyPermit,
    ) -> Result<(), ManifestError> {
        let section = self
            .doc
            .entry("optionalDependencies".to_string())
            .or_insert_with(|| Value::Object(Map::new()))
            .as_object_mut()
            .ok_or_else(|| ManifestError::FormattingNotPreserved {
                path: self.path.clone(),
                message: "optionalDependencies is not an object".to_string(),
            })?;

        for (name, ver) in updates {
            section.insert(name.clone(), Value::String(ver.render().to_string()));
        }

        Ok(())
    }

    fn npm_role(&self) -> Option<NpmRole> {
        npm_role_from_doc(&self.doc)
    }

    fn bin_names(&self) -> Vec<String> {
        match self.doc.get("bin") {
            // npm installs a string `bin` under the unscoped package name.
            Some(Value::String(_)) => npm_package_name(&self.doc)
                .map(|name| name.rsplit('/').next().unwrap_or(name).to_string())
                .into_iter()
                .collect(),
            Some(Value::Object(bins)) => bins.keys().cloned().collect(),
            _ => Vec::new(),
        }
    }
}

fn parse_npm_spec_str(s: &str, ws_kind: Option<WorkspaceKind>) -> DepSpec {
    if let Some(rest) = s.strip_prefix("workspace:") {
        if let Some(kind) = ws_kind {
            return DepSpec::Workspace(kind);
        }
        return DepSpec::Opaque(format!("workspace:{rest}"));
    }
    if let Some(rest) = s.strip_prefix("catalog:") {
        let name = if rest.is_empty() { None } else { Some(rest.to_string()) };
        return DepSpec::Catalog(name);
    }

    if crate::common::is_bare_semver(s) {
        if let Ok(v) = Version::parse(s, VersionGrammar::SemVer) {
            return DepSpec::Exact(v);
        }
    }

    if let Ok(req) = VersionReq::parse(s, Ecosystem::Npm) {
        return DepSpec::Range(req, s.to_string());
    }

    DepSpec::Opaque(s.to_string())
}

pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
    match spec {
        DepSpec::Exact(_) => Some(DepSpec::Exact(target.clone())),
        DepSpec::Range(_, original) => {
            let (prefix, rest) = crate::common::split_single_operator_prefix(orig…4723 tokens truncated…g()),
            &permit(),
        );

        assert!(
            result.is_err(),
            "update must fail when dep is absent from primary section"
        );

        let after_overrides = manifest.doc.get("overrides").cloned();
        let after_resolutions = manifest.doc.get("resolutions").cloned();

        assert_eq!(
            before_overrides, after_overrides,
            "overrides table must remain unchanged when the primary section update fails"
        );
        assert_eq!(
            before_resolutions, after_resolutions,
            "resolutions table must remain unchanged when the primary section update fails"
        );
    }

    // --- Nested overrides object must not be replaced with a string ---

    /// When `overrides["foo"]` is a nested object (e.g. `{ "bar": "^1.0.0" }`),
    /// bumping `foo` must leave that object intact. The nested form expresses a
    /// package-level constraint that is not a simple version pin and must not be
    /// overwritten.
    #[test]
    fn update_dependency_spec_does_not_overwrite_nested_overrides_object() {
        let dir = tempdir().unwrap();
        let content = r#"{
  "name": "@myorg/pkg",
  "version": "1.0.0",
  "dependencies": {
    "foo": "^1.0.0"
  },
  "overrides": {
    "foo": {
      "bar": "^1.0.0"
    }
  }
}
"#;
        let mut manifest = open_manifest(&dir, content);

        manifest
            .update_dependency_spec(
                "foo",
                DepKind::Runtime,
                DepSpec::Opaque("^2.0.0".to_string()),
                &permit(),
            )
            .unwrap();

        let overrides_foo = manifest
            .doc
            .get("overrides")
            .and_then(|v| v.as_object())
            .and_then(|o| o.get("foo"))
            .expect("overrides.foo must still exist");

        assert!(
            overrides_foo.is_object(),
            "overrides.foo must remain an object, but got: {overrides_foo:?}"
        );
    }

    // --- DepKind::Dev validate-before-mutate path ---

    #[test]
    fn update_dependency_spec_does_not_mutate_overrides_when_dev_dep_missing() {
        let dir = tempdir().unwrap();
        let content = r#"{
  "name": "@myorg/pkg",
  "version": "1.0.0",
  "devDependencies": {
    "typescript": "^5.0.0"
  },
  "overrides": {
    "lodash": "^4.17.0"
  }
}
"#;
        let mut manifest = open_manifest(&dir, content);

        let before = manifest.doc.get("overrides").cloned();

        let result =
            manifest.update_dependency_spec("lodash", DepKind::Dev, DepSpec::Opaque("^5.0.0".to_string()), &permit());

        assert!(
            result.is_err(),
            "update must fail when dep is absent from devDependencies"
        );

        let after = manifest.doc.get("overrides").cloned();
        assert_eq!(
            before, after,
            "overrides table must remain unchanged when the dev dep update fails"
        );
    }

    /// A package.json that contains a top-level `"workspaces"` array must be
    /// detected as an NPM workspace root by `detect_npm_workspace_kind`, even
    /// when no lock-file is present on disk (the lock-file heuristic alone is
    /// not sufficient for projects that have not yet run `npm install`).
    #[test]
    fn detects_workspace_kind_from_workspaces_field_in_package_json() {
        let dir = tempdir().unwrap();
        let pkg_json = dir.path().join("package.json");
        let content = r#"{
  "name": "my-monorepo",
  "version": "1.0.0",
  "workspaces": [
    "packages/*"
  ]
}
"#;
        fs::write(&pkg_json, content).unwrap();

        // No lock-file on disk, only the "workspaces" field in package.json.
        let kind = detect_npm_workspace_kind(dir.path()).unwrap();
        assert_eq!(
            kind,
            Some(WorkspaceKind::Npm),
            "workspaces field in package.json must imply WorkspaceKind::Npm"
        );
    }

    /// A scoped package name like `"@scope/name"` must round-trip through
    /// `package_name()` unchanged. Scoped names contain a `/` character that
    /// could be mistaken for a path separator; this test verifies it is
    /// treated as a literal package-name character.
    #[test]
    fn scoped_package_name_is_parsed_correctly() {
        let dir = tempdir().unwrap();
        let content = r#"{
  "name": "@my-scope/awesome-pkg",
  "version": "2.3.4"
}
"#;
        let manifest = open_manifest(&dir, content);
        assert_eq!(
            manifest.package_name().unwrap(),
            "@my-scope/awesome-pkg",
            "scoped package name must be returned verbatim"
        );
    }

    /// A `package.json` that is missing the `"version"` field must make
    /// `current_version()` return `Err(ManifestError::MissingField)` rather
    /// than panicking or returning a default value.
    #[test]
    fn missing_version_field_returns_missing_field_error_not_panic() {
        let dir = tempdir().unwrap();
        let content = r#"{
  "name": "no-version-pkg",
  "description": "This package intentionally omits the version field"
}
"#;
        let manifest = open_manifest(&dir, content);
        let result = manifest.current_version();
        assert!(
            matches!(result, Err(ManifestError::MissingField { field: "version", .. })),
            "missing version field must return MissingField error, got: {result:?}"
        );
    }

    #[test]
    fn npm_declares_private_reads_the_private_field() {
        assert!(npm_declares_private(r#"{"name":"root","private":true}"#));
        assert!(!npm_declares_private(r#"{"name":"root","private":false}"#));
        assert!(!npm_declares_private(r#"{"name":"root"}"#));
        assert!(!npm_declares_private("not json"));
    }

    /// Tab-indented package.json files must have their indentation preserved after a
    /// version write. This catches regressions where the CST editor re-serializes with
    /// two-space indentation instead of the original tab characters.
    #[test]
    fn tab_indentation_is_preserved_after_version_write() {
        use callisto_model::WorkspaceKind;
        let dir = tempdir().unwrap();
        let path = dir.path().join("package.json");
        let content = "{\n\t\"name\": \"tab-app\",\n\t\"version\": \"1.0.0\"\n}\n";
        fs::write(&path, content).unwrap();

        let decl = ManifestDecl::new("package.json", ManifestRole::Canonical, ManifestFormat::PackageJson).unwrap();
        let ctx = OpenContext {
            workspace_root: dir.path(),
            cargo_workspace: None,
            npm_workspace_kind: Some(WorkspaceKind::Pnpm),
        };

        let mut pj = PackageJson::open(&decl, &ctx).unwrap();
        pj.write_version(
            &callisto_model::Version::parse("1.1.0", callisto_model::VersionGrammar::SemVer).unwrap(),
            &permit(),
        )
        .unwrap();
        pj.persist(&permit()).unwrap();

        let updated = fs::read_to_string(&path).unwrap();
        assert!(updated.contains("\"version\": \"1.1.0\""));
        assert!(
            updated.contains("\t\"version\""),
            "tab indentation must be preserved after version write"
        );
    }

    /// Regression lock for the `npm.rs` half of F4's shared-fingerprint
    /// migration: a `package.json` with CRLF line endings must keep them
    /// across a `write_version` + `persist` round trip. `npm.rs` previously
    /// had its own private `LineEnding` detection/reapply logic (now
    /// migrated onto `crate::common::FormatFingerprint`) but no test ever
    /// exercised the CRLF branch directly.
    #[test]
    fn preserves_crlf_line_endings_on_write() {
        let dir = tempdir().unwrap();
        let path = dir.path().join("package.json");
        let content = "{\r\n  \"name\": \"crlf-app\",\r\n  \"version\": \"1.0.0\"\r\n}\r\n";
        fs::write(&path, content).unwrap();

        let decl = ManifestDecl::new("package.json", ManifestRole::Canonical, ManifestFormat::PackageJson).unwrap();
        let ctx = OpenContext {
            workspace_root: dir.path(),
            cargo_workspace: None,
            npm_workspace_kind: None,
        };

        let mut pj = PackageJson::open(&decl, &ctx).unwrap();
        pj.write_version(
            &callisto_model::Version::parse("1.1.0", callisto_model::VersionGrammar::SemVer).unwrap(),
            &permit(),
        )
        .unwrap();
        pj.persist(&permit()).unwrap();

        let updated_bytes = fs::read(&path).unwrap();
        let updated = String::from_utf8(updated_bytes).unwrap();

        assert!(
            !updated.starts_with('\u{FEFF}'),
            "expected no BOM to be introduced, got:\n{updated:?}"
        );
        assert!(
            updated.contains("\r\n"),
            "expected CRLF line endings to survive write, got:\n{updated:?}"
        );
        assert!(
            !updated.replace("\r\n", "").contains('\n'),
            "expected no bare LF line endings to remain, got:\n{updated:?}"
        );
        assert!(updated.contains("\"version\": \"1.1.0\""));
    }

    // --- round_trip tests ---------------------------------------------------

    fn make_npm_spec(raw: &str) -> DepSpec {
        let req = VersionReq::parse(raw, Ecosystem::Npm).unwrap();
        DepSpec::Range(req, raw.to_string())
    }

    fn npm_version(s: &str) -> Version {
        Version::parse(s, VersionGrammar::SemVer).unwrap()
    }

    fn raw_of(spec: Option<DepSpec>) -> Option<String> {
        match spec {
            Some(DepSpec::Range(_, raw)) => Some(raw),
            _ => None,
        }
    }

    #[test]
    fn round_trip_exact_spec_rewrites_to_target_version() {
        let spec = DepSpec::Exact(npm_version("1.0.0"));
        let target = npm_version("2.3.4");
        match round_trip(&spec, &target) {
            Some(DepSpec::Exact(v)) => assert_eq!(v.render(), "2.3.4"),
            other => panic!("expected Some(Exact(2.3.4)), got {other:?}"),
        }
    }

    #[test]
    fn round_trip_caret_range_rewrites_to_target_version() {
        let spec = make_npm_spec("^1.0.0");
        let target = npm_version("1.5.2");
        assert_eq!(raw_of(round_trip(&spec, &target)).as_deref(), Some("^1.5.2"));
    }

    #[test]
    fn round_trip_tilde_range_rewrites_to_target_version() {
        let spec = make_npm_spec("~1.0.0");
        let target = npm_version("1.0.9");
        assert_eq!(raw_of(round_trip(&spec, &target)).as_deref(), Some("~1.0.9"));
    }

    #[test]
    fn round_trip_gte_range_rewrites_to_target_version() {
        let spec = make_npm_spec(">=1.0.0");
        let target = npm_version("2.5.1");
        assert_eq!(raw_of(round_trip(&spec, &target)).as_deref(), Some(">=2.5.1"));
    }

    #[test]
    fn round_trip_exact_operator_range_rewrites_to_target_version() {
        let spec = make_npm_spec("=1.0.0");
        let target = npm_version("1.2.3");
        assert_eq!(raw_of(round_trip(&spec, &target)).as_deref(), Some("=1.2.3"));
    }

    #[test]
    fn round_trip_preserves_two_part_precision() {
        let spec = make_npm_spec("^1.0");
        let target = npm_version("1.5.2");
        assert_eq!(raw_of(round_trip(&spec, &target)).as_deref(), Some("^1.5"));
    }

    #[test]
    fn round_trip_preserves_one_part_precision() {
        let spec = make_npm_spec("^1");
        let target = npm_version("2.5.2");
        assert_eq!(raw_of(round_trip(&spec, &target)).as_deref(), Some("^2"));
    }

    /// A prerelease target version (e.g. publishing `2.0.0-beta.1`) must be
    /// rendered in full, not truncated to `major.minor.patch` -- dropping the
    /// prerelease suffix would produce a range that does not actually match
    /// the version it claims to pin to (`^2.0.0` excludes `2.0.0-beta.1`
    /// under semver precedence rules).
    #[test]
    fn round_trip_prerelease_target_is_rendered_in_full() {
        let spec = make_npm_spec("^1.0.0");
        let target = npm_version("2.0.0-beta.1");
        assert_eq!(raw_of(round_trip(&spec, &target)).as_deref(), Some("^2.0.0-beta.1"));
    }

    #[test]
    fn round_trip_non_range_variants_return_none() {
        let target = npm_version("2.0.0");
        assert!(round_trip(&DepSpec::Opaque("weird".to_string()), &target).is_none());
        assert!(round_trip(&DepSpec::Workspace(WorkspaceKind::Npm), &target).is_none());
        assert!(round_trip(&DepSpec::Catalog(None), &target).is_none());
        assert!(round_trip(&DepSpec::CargoBare(npm_version("1.0.0")), &target).is_none());
    }

    /// A clause with a prerelease suffix (e.g. `^1.0.0-beta.1`) is declined
    /// rather than rewritten -- `render_at_precision` only knows how to
    /// truncate a plain `major.minor.patch` clause, so a prerelease-qualified
    /// original clause safely falls back to `RewriteOutcome::LeftAlone`.
    #[test]
    fn round_trip_prerelease_clause_returns_none() {
        let spec = make_npm_spec("^1.0.0-beta.1");
        let target = npm_version("2.0.0");
        assert!(round_trip(&spec, &target).is_none());
    }

    /// A wildcard clause (`1.x`, `1.X`, `^1.x`) is declined rather than
    /// rewritten -- these are not simple `{operator}{version}` clauses and
    /// `render_at_precision` has no wildcard-preserving behavior.
    #[test]
    fn round_trip_wildcard_clause_returns_none() {
        let target = npm_version("2.5.0");
        assert!(round_trip(&make_npm_spec("1.x"), &target).is_none());
        assert!(round_trip(&make_npm_spec("1.X"), &target).is_none());
        assert!(round_trip(&make_npm_spec("^1.x"), &target).is_none());
    }

    /// A comma-separated compound range (`>=1.0.0, <2.0.0`) parses
    /// successfully -- npm and Cargo share the same underlying semver
    /// requirement grammar in this codebase (`semver::VersionReq`), so this
    /// atypical-for-npm-but-syntactically-valid form does reach this
    /// function -- but it is declined rather than rewritten. Unlike
    /// `cargo::round_trip`, `npm::round_trip` has no per-clause compound-range
    /// handling, so this documents current, intentional (safe-fallback)
    /// behavior: the caller falls back to `RewriteOutcome::LeftAlone` with a
    /// diagnostic instead of guessing at a rewrite.
    #[test]
    fn round_trip_comma_compound_range_returns_none() {
        let spec = make_npm_spec(">=1.0.0, <2.0.0");
        let target = npm_version("1.5.0");
        assert!(round_trip(&spec, &target).is_none());
    }

    #[test]
    fn persist_is_exposed_as_a_manifest_trait_method() {
        let dir = tempdir().unwrap();
        let content = "{\n  \"name\": \"@myorg/pkg\",\n  \"version\": \"1.0.0\"\n}\n";
        let manifest_path = dir.path().join("package.json");
        let mut manifest = open_manifest(&dir, content);

        <PackageJson as Manifest>::persist(&mut manifest, &permit()).unwrap();

        let after = fs::read_to_string(&manifest_path).unwrap();
        assert_eq!(
            after, content,
            "persist() with no prior mutation must reproduce the file unchanged"
        );
    }

    // --- npm_role tests (F23: moved from callisto-graph::walk's detect_npm_role) ---

    /// F23 regression: `npm_role()` must derive the platform role from the
    /// `Manifest` handle's already-parsed document, not a fresh disk read.
    /// Proven by deleting the underlying file after `open()` and confirming
    /// `npm_role()` still reports the correct role -- a re-implementation
    /// that shelled out to a fresh `fs::read` internally would instead
    /// silently report `None` here.
    #[test]
    fn npm_role_does_not_re_read_the_manifest_from_disk() {
        let dir = tempdir().unwrap();
        let manifest_path = dir.path().join("package.json");
        fs::write(
            &manifest_path,
            r#"{"name":"@scope/my-lib-linux-x64-gnu","version":"1.0.0","os":["linux"],"cpu":["x64"]}"#,
        )
        .unwrap();
        let manifest = open_manifest(&dir, &fs::read_to_string(&manifest_path).unwrap());

        fs::remove_file(&manifest_path).unwrap();

        let role = manifest.npm_role();
        assert_eq!(
            role,
            Some(NpmRole::Platform {
                platform: "linux".to_string(),
                arch: "x64".to_string(),
                abi: Some("gnu".to_string()),
            }),
            "npm_role() must still resolve correctly from the in-memory document \
             after the underlying file is gone, proving it does no second read"
        );
    }

    #[test]
    fn npm_role_is_none_for_a_plain_non_platform_package() {
        let dir = tempdir().unwrap();
        let manifest = open_manifest(&dir, r#"{"name":"plain-pkg","version":"1.0.0"}"#);
        assert_eq!(manifest.npm_role(), None);
    }

    #[test]
    fn npm_role_from_doc_infers_linux_gnu_abi_from_package_name_suffix() {
        let doc: Map<String, Value> = serde_json::from_str(
            r#"{"name":"@scope/my-lib-linux-x64-gnu","version":"1.0.0","os":["linux"],"cpu":["x64"]}"#,
        )
        .unwrap();
        assert_eq!(
            npm_role_from_doc(&doc),
            Some(NpmRole::Platform {
                platform: "linux".to_string(),
                arch: "x64".to_string(),
                abi: Some("gnu".to_string()),
            })
        );
    }

    #[test]
    fn npm_role_from_doc_infers_linux_musl_abi_from_package_name_suffix() {
        let doc: Map<String, Value> = serde_json::from_str(
            r#"{"name":"@scope/my-lib-linux-arm64-musl","version":"1.0.0","os":["linux"],"cpu":["arm64"]}"#,
        )
        .unwrap();
        assert_eq!(
            npm_role_from_doc(&doc),
            Some(NpmRole::Platform {
                platform: "linux".to_string(),
                arch: "arm64".to_string(),
                abi: Some("musl".to_string()),
            })
        );
    }

    #[test]
    fn npm_role_from_doc_infers_linux_gnueabihf_abi_from_package_name_suffix() {
        let doc: Map<String, Value> = serde_json::from_str(
            r#"{"name":"@scope/my-lib-linux-arm-gnueabihf","version":"1.0.0","os":["linux"],"cpu":["arm"]}"#,
        )
        .unwrap();
        assert_eq!(
            npm_role_from_doc(&doc),
            Some(NpmRole::Platform {
                platform: "linux".to_string(),
                arch: "arm".to_string(),
                abi: Some("gnueabihf".to_string()),
            })
        );
    }

    /// Non-Linux platforms have no ABI concept -- must not be affected by the
    /// name-suffix inference at all.
    #[test]
    fn npm_role_from_doc_does_not_infer_abi_for_non_linux_platforms() {
        let doc: Map<String, Value> = serde_json::from_str(
            r#"{"name":"@scope/my-lib-darwin-arm64-gnu","version":"1.0.0","os":["darwin"],"cpu":["arm64"]}"#,
        )
        .unwrap();
        assert_eq!(
            npm_role_from_doc(&doc),
            Some(NpmRole::Platform {
                platform: "darwin".to_string(),
                arch: "arm64".to_string(),
                abi: None,
            })
        );
    }

    /// A Linux platform package whose name has no recognized ABI suffix at
    /// all stays `abi: None` -- this infers when it can, it doesn't invent an
    /// ABI that isn't actually signaled anywhere.
    #[test]
    fn npm_role_from_doc_leaves_abi_none_when_linux_name_has_no_recognized_suffix() {
        let doc: Map<String, Value> = serde_json::from_str(
            r#"{"name":"@scope/my-lib-linux-x64","version":"1.0.0","os":["linux"],"cpu":["x64"]}"#,
        )
        .unwrap();
        assert_eq!(
            npm_role_from_doc(&doc),
            Some(NpmRole::Platform {
                platform: "linux".to_string(),
                arch: "x64".to_string(),
                abi: None,
            })
        );
    }

    #[test]
    fn npm_role_from_doc_returns_none_when_os_or_cpu_missing() {
        let doc: Map<String, Value> = serde_json::from_str(r#"{"name":"plain-pkg","version":"1.0.0"}"#).unwrap();
        assert_eq!(npm_role_from_doc(&doc), None);
    }
}

