        serde_json::from_slice(&fs::read(root.join("crates/source/package.json")).unwrap()).unwrap();
    let snapshot_version = npm_owner["version"].as_str().unwrap();
    assert!(snapshot_version.starts_with("0.0.0-canary-"), "{npm_owner}");
