+    pub fn coverage(&self, version: &Version) -> Result<Coverage, GrammarMismatch> {
+        let Some(range) = self.range() else {
+            return Ok(Coverage::Covers);
+        };
+        // A full bare npm version is an exact pin, unlike Cargo's implicit caret.
+        let requirement = if Version::parse(range, VersionGrammar::SemVer).is_ok() {
+            VersionReq::parse(&format!("={range}"), Ecosystem::Npm)
+        } else if range.split('.').count() == 2
+            && range.split('.').all(|part| !part.is_empty() && part.bytes().all(|byte| byte.is_ascii_digit()))
+        {
