        assert_eq!(packed["dependencies"][name], expected);
    }
    assert_eq!(packed["dependencies"]["range"], "npm:@protocol/lib@^0.2.0");
    assert_eq!(packed["dependencies"]["path-lib"], "npm:@protocol/lib@0.2.3");
